CODICE = "U.A.1.2"
PREDEFINITA = "Tessere e bollini della sede centrale"
NOME = "Acquisto delle tessere (sede nazionale o federazione)"


def voce_tessere(apps, schema_editor):
    Voce = apps.get_model("tesoreria", "Voce")
    voce = Voce.objects.filter(codice=CODICE).first()
    if voce is None:
        padre = Voce.objects.filter(codice="U.A.1").first()
        if padre is None:
            return  # piano dei conti non ancora creato: lo crea la 0002 con la sottovoce
        Voce.objects.create(codice=CODICE, tipo=padre.tipo, sezione=padre.sezione,
                            numero=padre.numero, descrizione=NOME, padre=padre)
    elif voce.descrizione == PREDEFINITA:  # rinominata solo se nessuno l'ha cambiata
        voce.descrizione = NOME
        voce.save(update_fields=["descrizione"])



